/**
 * The catalog this build ships with (`bundled-snapshot.json`, generated by
 * `bun run generate:model-catalog`).
 *
 * Imported dynamically so its roughly 1 MB of data lands in an async chunk of
 * the main bundle rather than the initial one, whose byte budget it would
 * exceed (`scripts/lib/main-bundle-budget.mjs`). Verified before use: a
 * snapshot that does not hash to its stated name is a build defect and fails
 * boot instead of resolving models against damaged data.
 */
import { verifyModelCatalogDocument } from "./document.js";
import type { ModelCatalogDocument } from "../../shared/model-catalog/types.js";

export async function loadBundledModelCatalog(): Promise<ModelCatalogDocument> {
  const { default: snapshot } = await import("./bundled-snapshot.json", { with: { type: "json" } });
  return verifyModelCatalogDocument(snapshot);
}
